t.script:
                document.addEventListener('DOMContentLoaded', function () {
                    const btnVerify = document.getElementById('btn_verify_token');
                    const inputToken = document.getElementById('manual_token');
                    const resultDiv = document.getElementById('scan_result');
                    const btnToggleCam = document.getElementById('btn_toggle_camera');

                    let html5QrcodeScanner = null;
                    let isCameraRunning = false;

                    function processScan(scannedCode) {
                        const token = (scannedCode || inputToken.value).trim();
                        const action = document.querySelector('input[name="gate_action"]:checked').value;

                        if (!token) {
                            alert('Harap masukkan Kode Token QR!');
                            return;
                        }

                        btnVerify.disabled = true;
                        btnVerify.innerHTML = ' Memproses...';
                        resultDiv.className = 'd-none alert mt-3 text-start rounded-3 shadow-sm p-3';

                        const formData = new FormData();
                        formData.append('token', token);
                        formData.append('action', action);

                        fetch('/api/mahad/gate/verify', {
                            method: 'POST',
                            body: formData
                        })
                        .then(response => response.json())
                        .then(data => {
                            btnVerify.disabled = false;
                            btnVerify.innerHTML = ' Verifikasi';
                            resultDiv.classList.remove('d-none');

                            if (data.status === 'success') {
                                resultDiv.className = 'alert alert-success mt-3 text-start rounded-3 shadow-sm p-3';
                                resultDiv.innerHTML = `

 ${data.message}


Mahasantri: ${data.student_name}

No. Izin: ${data.permit_number}

Jenis: ${data.permit_type}
                                    ${data.destination ? `
Tujuan: ${data.destination}` : ''}
                                `;
                                inputToken.value = '';
                            } else if (data.status === 'warning') {
                                resultDiv.className = 'alert alert-warning mt-3 text-start rounded-3 shadow-sm p-3';
                                resultDiv.innerHTML = `
 ${data.message}`;
                            } else {
                                resultDiv.className = 'alert alert-danger mt-3 text-start rounded-3 shadow-sm p-3';
                                resultDiv.innerHTML = `
 ${data.message}`;
                            }
                        })
                        .catch(err => {
                            btnVerify.disabled = false;
                            btnVerify.innerHTML = ' Verifikasi';
                            resultDiv.classList.remove('d-none');
                            resultDiv.className = 'alert alert-danger mt-3 text-start rounded-3 shadow-sm p-3';
                            resultDiv.innerHTML = `
 Terjadi kesalahan server/koneksi.`;
                        });
                    }

                    function startCameraScanner() {
                        if (isCameraRunning) return;
                        html5QrcodeScanner = new Html5QrcodeScanner("reader", { fps: 10, qrbox: { width: 220, height: 220 } });
                        html5QrcodeScanner.render((decodedText) => {
                            inputToken.value = decodedText;
                            processScan(decodedText);
                        }, (error) => {
                            // ignore scan errors
                        });
                        isCameraRunning = true;
                        btnToggleCam.innerHTML = ' Matikan Kamera Scanner';
                        btnToggleCam.className = 'btn btn-sm btn-outline-danger rounded-pill px-3';
                    }

                    function stopCameraScanner() {
                        if (html5QrcodeScanner && isCameraRunning) {
                            html5QrcodeScanner.clear().catch(error => console.error(error));
                            isCameraRunning = false;
                            btnToggleCam.innerHTML = ' Buka Kamera Scanner';
                            btnToggleCam.className = 'btn btn-sm btn-outline-primary rounded-pill px-3';
                        }
                    }

                    btnToggleCam.addEventListener('click', function() {
                        if (isCameraRunning) {
                            stopCameraScanner();
                        } else {
                            startCameraScanner();
                        }
                    });

                    btnVerify.addEventListener('click', () => processScan());
                    inputToken.addEventListener('keypress', function (e) {
                        if (e.key === 'Enter') {
                            processScan();
                        }
                    });
                });
